describe('Product Image Pinch-to-Zoom', () => {
  beforeEach(() => {
    cy.visit('/product/test-product');
    cy.get('[data-testid="product-image"]').should('be.visible');
  });

  it('should zoom in when user performs pinch gesture on product image', () => {
    const imageSelector = '[data-testid="product-image"]';

    cy.get(imageSelector).then(($image) => {
      const initialWidth = $image.width();

      cy.get(imageSelector)
        .trigger('touchstart', {
          touches: [
            { clientX: 100, clientY: 100 },
            { clientX: 200, clientY: 200 }
          ]
        })
        .trigger('touchmove', {
          touches: [
            { clientX: 80, clientY: 80 },
            { clientX: 220, clientY: 220 }
          ],
          changedTouches: [
            { clientX: 80, clientY: 80 },
            { clientX: 220, clientY: 220 }
          ]
        })
        .trigger('touchend', {
          changedTouches: []
        });

      cy.get(imageSelector).then(($zoomedImage) => {
        const zoomedWidth = $zoomedImage.width();
        expect(zoomedWidth).to.be.greaterThan(initialWidth);
      });
    });
  });

  it('should zoom out when user performs reverse pinch gesture on product image', () => {
    const imageSelector = '[data-testid="product-image"]';

    cy.get(imageSelector).then(($image) => {
      const initialWidth = $image.width();

      cy.get(imageSelector)
        .trigger('touchstart', {
          touches: [
            { clientX: 80, clientY: 80 },
            { clientX: 220, clientY: 220 }
          ]
        })
        .trigger('touchmove', {
          touches: [
            { clientX: 100, clientY: 100 },
            { clientX: 200, clientY: 200 }
          ],
          changedTouches: [
            { clientX: 100, clientY: 100 },
            { clientX: 200, clientY: 200 }
          ]
        })
        .trigger('touchend', {
          changedTouches: []
        });

      cy.get(imageSelector).then(($zoomedOutImage) => {
        const zoomedOutWidth = $zoomedOutImage.width();
        expect(zoomedOutWidth).to.be.lessThan(initialWidth);
      });
    });
  });

  it('should not zoom beyond maximum zoom level', () => {
    const imageSelector = '[data-testid="product-image"]';
    const maxZoomLevel = 3;

    cy.get(imageSelector).should('have.attr', 'data-max-zoom', maxZoomLevel.toString());

    for (let i = 0; i < 5; i++) {
      cy.get(imageSelector)
        .trigger('touchstart', {
          touches: [
            { clientX: 100, clientY: 100 },
            { clientX: 200, clientY: 200 }
          ]
        })
        .trigger('touchmove', {
          touches: [
            { clientX: 50, clientY: 50 },
            { clientX: 250, clientY: 250 }
          ],
          changedTouches: [
            { clientX: 50, clientY: 50 },
            { clientX: 250, clientY: 250 }
          ]
        })
        .trigger('touchend', {
          changedTouches: []
        });
    }

    cy.get(imageSelector).then(($image) => {
      const transform = $image.css('transform');
      const scaleMatch = transform.match(/scale\(([\d.]+)/);
      const currentScale = scaleMatch ? parseFloat(scaleMatch[1]) : 1;
      expect(currentScale).to.be.lessThanOrEqual(maxZoomLevel);
    });
  });

  it('should maintain zoom level when user stops pinching', () => {
    const imageSelector = '[data-testid="product-image"]';

    cy.get(imageSelector)
      .trigger('touchstart', {
        touches: [
          { clientX: 100, clientY: 100 },
          { clientX: 200, clientY: 200 }
        ]
      })
      .trigger('touchmove', {
        touches: [
          { clientX: 80, clientY: 80 },
          { clientX: 220, clientY: 220 }
        ],
        changedTouches: [
          { clientX: 80, clientY: 80 },
          { clientX: 220, clientY: 220 }
        ]
      })
      .trigger('touchend', {
        changedTouches: []
      });

    cy.get(imageSelector).then(($image) => {
      const transformAfterZoom = $image.css('transform');

      cy.wait(500);

      cy.get(imageSelector).then(($imageAfterWait) => {
        const transformAfterWait = $imageAfterWait.css('transform');
        expect(transformAfterWait).to.equal(transformAfterZoom);
      });
    });
  });

  it('should reset zoom when double-tapping product image', () => {
    const imageSelector = '[data-testid="product-image"]';

    cy.get(imageSelector)
      .trigger('touchstart', {
        touches: [
          { clientX: 100, clientY: 100 },
          { clientX: 200, clientY: 200 }
        ]
      })
      .trigger('touchmove', {
        touches: [
          { clientX: 80, clientY: 80 },
          { clientX: 220, clientY: 220 }
        ],
        changedTouches: [
          { clientX: 80, clientY: 80 },
          { clientX: 220, clientY: 220 }
        ]
      })
      .trigger('touchend', {
        changedTouches: []
      });

    cy.get(imageSelector).dblclick();

    cy.get(imageSelector).then(($image) => {
      const transform = $image.css('transform');
      expect(transform).to.match(/scale\(1\)/);
    });
  });
});
